        var allText = extracted.columns.map(function () { return null; });
        if (parsed._noSelect || !extracted.columns.length) return allText;
        if (parsed.clauses && parsed.clauses.union && parsed.clauses.union.length > 1) return allText;
        var byName = ensureIndex(schema);
