        OR: 1,
        WHERE: 1,
        GROUP: 1,
        ORDER: 1,
        HAVING: 1,
        UNION: 1,
        EXCEPT: 1,
        INTERSECT: 1,
        JOIN: 1,
        INNER: 1,
        FULL: 1,
        CROSS: 1,
        OUTER: 1,
        ON: 1,
        THEN: 1
