    var STRICT_KEYWORD_LITERALS = {
        CURRENT_TIMESTAMP: 1, CURRENT_USER: 1, CURRENT_DATE: 1, CURRENT_TIME: 1,
        SESSION_USER: 1, SYSTEM_USER: 1, USER: 1
    };

    /**
     * @function StrictError
     * @description Wraps one strict-parser error object so it can be thrown and distinguished from any other exception by an instanceof StrictError check.
     * @param {Object} err - The error object produced by strictMkErr.
     */
    function StrictError(err) { this.err = err; }

    /**
     * @function strictNearDesc
     * @description Describes the token an error occurred near, for use in a near-this-token error message suffix.
     * @param {Object} tok - The offending token, or the synthetic end-of-query token.
     * @returns {string} The end of the query, the keyword's upper-cased form, or the token's quoted value.
     */
