    /**
     * @method isWordAny
     * @description Tests whether the current token is a keyword or identifier matching any of the given uppercase words.
     * @param {Array<string>} words - Uppercase words to match against the current token's upper.
     * @returns {boolean} True when the current token matches one of words.
     */
    StrictParser.prototype.isWordAny = function (words) {
        var t = this.cur();
        if (!t || (t.type !== 'keyword' && t.type !== 'identifier')) return false;
        return words.indexOf(t.upper) !== -1;
    };
    /**
     * @method isWordAt
     * @description Tests whether the token at this.pos plus offset is a keyword or identifier matching the given uppercase word.
     * @param {number} offset - Offset from the current position.
     * @param {string} word - Uppercase word to match.
     * @returns {boolean} True when the token at that offset matches word.
     */
    StrictParser.prototype.isWordAt = function (offset, word) {
        var t = this.at(offset);
        return !!t && t.upper === word && (t.type === 'keyword' || t.type === 'identifier');
    };
    /**
     * @method isPunct
     * @description Tests whether the current token is a punctuation token with the given value.
     * @param {string} v - Punctuation character to match, e.g. '(' or ','.
     * @returns {boolean} True when the current token is that punctuation.
     */
    StrictParser.prototype.isPunct = function (v) { var t = this.cur(); return !!t && t.type === 'punct' && t.value === v; };
    /**
     * @method isPunctAt
     * @description Tests whether the token at this.pos plus offset is a punctuation token with the given value.
     * @param {number} offset - Offset from the current position.
     * @param {string} v - Punctuation character to match.
     * @returns {boolean} True when the token at that offset is that punctuation.
     */
    StrictParser.prototype.isPunctAt = function (offset, v) { var t = this.at(offset); return !!t && t.type === 'punct' && t.value === v; };
    /**
     * @method isOp
     * @description Tests whether the current token is an operator token with the given value.
     * @param {string} v - Operator text to match, e.g. '+' or '*'.
     * @returns {boolean} True when the current token is that operator.
     */
    StrictParser.prototype.isOp = function (v) { var t = this.cur(); return !!t && t.type === 'operator' && t.value === v; };

    /**
     * @method advance
     * @description Returns the current token and moves the parser's position one token forward, recording the consumed token as this._prevTok for error-message context.
     * @returns {Object} The token that was just consumed, or undefined at the end of the range.
     */
    StrictParser.prototype.advance = function () {
        var t = this.cur();
        if (t) {
            this.pos++;
            this._prevTok = t;
        };
        return t;
    };

    /**
     * @method eofToken
     * @description Builds a synthetic end-of-query token positioned right after the last real token in range, for error reporting when parsing runs past the end of the statement.
     * @returns {Object} A token-shaped object with __eof set to true.
     */
    StrictParser.prototype.eofToken = function () {
        var t = this.tokens[this.end];
        var pos, line, col;
        if (t) { pos = t.start; line = t.line; col = t.col; }
        else {
            var last = this.tokens[this.end - 1];
            pos = last ? last.end : 0;
            var lc = lineColAt(this.lineIndex, pos);
            line = lc.line; col = lc.col;
        };
        return {
            start: pos,
            end: pos,
            line: line,
            col: col,
            value: '',
            __eof: true
        };
    };

    /**
     * @method setFallback
     * @description Sets the missing-expression fallback hint used by failExpected(), returning the previous hint so the caller can restore it afterward.
     * @param {string} hint - New fallback hint text.
     * @returns {string} The previous fallback hint.
     */
    StrictParser.prototype.setFallback = function (hint) { var prev = this.exprFallback; this.exprFallback = hint; return prev; };
    /**
     * @method restoreFallback
     * @description Restores a previously saved fallback hint, undoing a setFallback() call.
     * @param {string} prev - Fallback hint to restore, as returned by setFallback().
     */
    StrictParser.prototype.restoreFallback = function (prev) { this.exprFallback = prev; };

    /**
     * @method fail
     * @description Throws a StrictError for a generic not-valid-here syntax problem at the given token, appending a near-this-token description to the message.
     * @param {Object} tok - Token the error occurred at, or null to use the end-of-query token.
     * @param {string} hint - Short how-to-fix-it hint.
     */
    StrictParser.prototype.fail = function (tok, hint) {
        var t = tok || this.eofToken();
        var near = strictNearDesc(t);
        var full = (hint || 'This is not valid here. Fix the syntax') + ', near ' + near + '.';
        throw new StrictError(strictMkErr(this.lineIndex, t, t, full, hint || ''));
    };
    /**
     * @method failWithFix
     * @description Throws a StrictError exactly like fail(), but also attaches a quick-fix descriptor to the error so lint()'s MCE000 finding carries a fixes entry.
     * @param {Object} tok - Token the error occurred at, or null to use the end-of-query token.
     * @param {string} hint - Short how-to-fix-it hint, already a complete sentence.
     * @param {Object} fix - Quick-fix descriptor: {title, edits, isSafe, isInFixAll}.
     */
    StrictParser.prototype.failWithFix = function (tok, hint, fix) {
        var t = tok || this.eofToken();
        throw new StrictError(strictMkErr(this.lineIndex, t, t, hint, '', fix));
    };
    /**
     * @method failBare
     * @description Throws a StrictError with an already-complete message, without appending a near-this-token suffix, for errors, such as an unclosed '(' or unterminated string, that already name the exact problem.
     * @param {Object} startTok - First token of the error span.
     * @param {Object} endTok - Last token of the error span, defaults to startTok.
     * @param {string} message - Full, already-complete error message.
     */
    StrictParser.prototype.failBare = function (startTok, endTok, message) {
        throw new StrictError(strictMkErr(this.lineIndex, startTok, endTok || startTok, message, ''));
    };
    /**
     * @method failExpected
     * @description Throws a StrictError for a missing expression at the current position, using a more specific end-of-query hint when the previous token was an operator or a continuation keyword such as AND, OR or IN, or the given fallback hint otherwise.
     * @param {string} fallbackHint - Hint to use when no more specific one applies.
     */
    StrictParser.prototype.failExpected = function (fallbackHint) {
        var tok = this.cur() || this.eofToken();
        var prev = this._prevTok;
        var isOpLike = !!prev && (prev.type === 'operator' || (prev.type === 'keyword' && STRICT_BIN_CONTINUATION[prev.upper]));
        var hint = isOpLike ? ("The query ends right after '" + prev.value + "'. Add the missing value or column") : (fallbackHint || 'An expression is missing here. Add a column, value or expression');
        this.fail(tok, hint);
    };

    /**
     * @method expectWord
     * @description Consumes the current token if it matches word, via isWord, otherwise throws a StrictError using hint.
     * @param {string} word - Uppercase word the current token must match.
     * @param {string} hint - Hint to use in the error if the word is missing.
     * @returns {Object} The consumed token.
     */
    StrictParser.prototype.expectWord = function (word, hint) {
        if (this.isWord(word)) return this.advance();
        this.fail(this.cur(), hint);
    };

    // A scalar expression (column, literal, function call, arithmetic, ...)
    // sitting where WHERE/HAVING/ON/a searched CASE's WHEN, or an AND/OR/NOT
    // operand, needs a predicate. Deliberately a different template from
    // fail()'s "Incorrect syntax near..." - this is not a syntax error, it is
    // a type error T-SQL itself reports this way.
    /**
     * @method failNonBoolean
     * @description Throws a StrictError reporting that a value-typed expression was used where a yes-or-no condition is required, such as a bare column in a WHERE clause, which is a type error rather than a syntax error.
     * @param {Object} tok - Token the error occurred at, or null to use the end-of-query token.
     */
    StrictParser.prototype.failNonBoolean = function (tok) {
        var t = tok || this.eofToken();
        var hint = 'Compare it to something, for example a = 1';
        var full = 'This is a value, not a yes-or-no condition. ' + hint + ', near ' + strictNearDesc(t) + '.';
        throw new StrictError(strictMkErr(this.lineIndex, t, t, full, hint));
    };

    /**
     * @method expectCloseParen
     * @description Consumes a ')' if the current token is one, otherwise throws a StrictError naming the unmatched '(' opened at openTok. When the token in the way is a word, the message names that word and does not tell the user to add a ) the query may not lack: JSON_VALUE(x, '$.a' RETURNING INT) has its ), and an added one makes it worse.
     * @param {Object} openTok - The '(' token this close paren is expected to match.
     * @returns {Object} The consumed ')' token.
     */
    StrictParser.prototype.expectCloseParen = function (openTok) {
        if (this.isPunct(')')) return this.advance();
        var t = this.cur();
        if (!t) this.failBare(openTok, openTok, 'This ( from line ' + openTok.line + ' is never closed. Add ) to close it, near the end of the query.');
        if (t.type === 'keyword' || t.type === 'identifier') {
            this.failBare(t, t, 'SQL Studio did not expect ' + t.raw + ' here. Check the arguments before it, or add ) to close the ( from line ' + openTok.line + '.');
        };
        this.fail(t, 'This ( from line ' + openTok.line + ' is missing its closing ). Add )');
    };

    // ---- expression grammar (full ladder) --------------------------------
    //
    // Every level below takes an `isEnforced` flag: falsy (the default, when a
    // caller omits it) means "value position" - the existing, permissive
    // behaviour, unchanged. `true` means "condition position" (WHERE/HAVING/
    // ON/a searched CASE's WHEN, and - by inheritance through this same
    // chain - every AND/OR/NOT operand of one of those): the parsed thing
    // must be predicate-shaped or parsing fails with the "non-boolean type"
    // message. `isEnforced` is only ever threaded through the FIRST/leftmost
    // operand at each level (the one candidate that could legitimately be
    // "just a parenthesised condition" or "just EXISTS(...)"); every other
    // operand (the right side of an operator, BETWEEN's/LIKE's/IN's operands,
    // a comparison's RHS, ...) is definitely a scalar position and is always
    // parsed with isEnforced=false, regardless of the caller's own mode.
    //
    // The arithmetic levels (parseBitwiseOr down to parsePrimary) return
    // { pure, bool }: `pure` is true only when nothing but a single,
    // unmodified primary was consumed at or below that level (no operator
    // applied), and `bool` (meaningful only when pure) says whether that one
    // primary is inherently boolean-shaped (EXISTS(...), or a parenthesised
    // group whose own content resolved to true). parsePredicate folds that
    // into a plain boolean: true when a comparison/BETWEEN/IN/LIKE/IS tail
    // was matched (any of those makes the whole predicate boolean regardless
    // of what `left` was), else `pure && bool` from the left operand alone.
    /**
     * @method parseOrExpr
     * @description Parses a chain of one or more AND-expressions joined by OR, the top level of the boolean expression grammar.
     * @param {boolean} [isEnforced] - True when the leftmost operand must be predicate-shaped, a condition position; propagated only to that operand.
     * @returns {boolean} True when the parsed expression is boolean-shaped.
     */
    StrictParser.prototype.parseOrExpr = function (isEnforced) {
        var isBooleanShaped = this.parseAndExpr(isEnforced);
        while (this.isWord('OR')) {
            this.advance();
            var r = this.parseAndExpr(isEnforced);
            isBooleanShaped = isEnforced ? true : (isBooleanShaped && r);
        };
        return isBooleanShaped;
    };
    /**
     * @method parseAndExpr
     * @description Parses a chain of one or more NOT-expressions joined by AND.
     * @param {boolean} [isEnforced] - True when the leftmost operand must be predicate-shaped; propagated only to that operand.
     * @returns {boolean} True when the parsed expression is boolean-shaped.
     */
    StrictParser.prototype.parseAndExpr = function (isEnforced) {
        var isBooleanShaped = this.parseNotExpr(isEnforced);
        while (this.isWord('AND')) {
            this.advance();
            var r = this.parseNotExpr(isEnforced);
            isBooleanShaped = isEnforced ? true : (isBooleanShaped && r);
        };
        return isBooleanShaped;
    };
    // The sole enforcement point: every leaf operand of a WHERE/HAVING/ON/
    // searched-CASE-WHEN condition passes through here exactly once (either
    // directly, or via parseAndExpr/parseOrExpr's loops), so one check here
    // covers the whole "operand of AND/OR/NOT" requirement with each
    // operand's own position.
    /**
     * @method parseNotExpr
     * @description Parses an optional leading NOT followed by a predicate; this is the single point every AND/OR operand passes through, so it is where the isEnforced, condition-position, check against a non-boolean value is actually raised.
     * @param {boolean} [isEnforced] - True when this operand must be predicate-shaped.
     * @returns {boolean} True when the parsed expression is boolean-shaped.
     */
    StrictParser.prototype.parseNotExpr = function (isEnforced) {
        if (this.isWord('NOT')) {
            this.advance();
            this.parseNotExpr(isEnforced);
            return true;
        };
        var tok = this.cur();
        var isBooleanShaped = this.parsePredicate(isEnforced);
        if (isEnforced && !isBooleanShaped) this.failNonBoolean(tok);
        return isEnforced ? true : isBooleanShaped;
    };
    /**
     * @method parsePredicate
     * @description Parses one predicate: an arithmetic expression optionally followed by a BETWEEN, IN, LIKE, IS or comparison-operator tail, with an optional leading NOT and, for a comparison, an optional ALL/ANY/SOME subquery.
     * @param {boolean} [isEnforced] - True when the leftmost operand must be predicate-shaped; propagated only to that operand.
     * @returns {boolean} True when a boolean-producing tail was matched, or the leftmost operand's own pure-boolean-ness otherwise.
     */
    StrictParser.prototype.parsePredicate = function (isEnforced) {
        var leftR = this.parseBitwiseOr(isEnforced);
        if (this.isWord('NOT') && (this.isWordAt(1, 'BETWEEN') || this.isWordAt(1, 'IN') || this.isWordAt(1, 'LIKE'))) {
            this.advance();
        };
        if (this.isWord('BETWEEN')) {
            this.advance();
            var fb1 = this.setFallback('BETWEEN needs a value after it. Add a value');
            this.parseBitwiseOr(false);
            this.restoreFallback(fb1);
            this.expectWord('AND', 'BETWEEN needs AND after the low value. Add AND');
            var fb2 = this.setFallback('BETWEEN needs a high value after AND. Add a value');
            this.parseBitwiseOr(false);
            this.restoreFallback(fb2);
            return true;
        };
        if (this.isWord('IN')) {
            this.advance();
            if (!this.isPunct('(')) this.fail(this.cur(), 'IN needs a parenthesized list or subquery. Add (');
            var openTok = this.advance();
            if (this.isWord('SELECT') || this.isWord('WITH')) {
                this.parseStatementBody();
            } else {
                var fb3 = this.setFallback('The IN list is missing a value. Add a value');
                this.parseOrExpr(false);
                while (this.isPunct(',')) {
                    this.advance();
                    this.parseOrExpr(false);
                };
                this.restoreFallback(fb3);
            };
            this.expectCloseParen(openTok);
            return true;
        };
        if (this.isWord('LIKE')) {
            this.advance();
            var fb4 = this.setFallback('LIKE needs a pattern to match. Add a pattern');
            this.parseBitwiseOr(false);
            this.restoreFallback(fb4);
            if (this.isWord('ESCAPE')) {
                this.advance();
                var fb5 = this.setFallback('ESCAPE needs the character it defines. Add an escape character');
                this.parseBitwiseOr(false);
                this.restoreFallback(fb5);
            };
            return true;
        };
        if (this.isWord('IS')) {
            this.advance();
            if (this.isWord('NOT')) this.advance();
            /* IS [NOT] DISTINCT FROM (SQL Server 2022): a NULL-safe comparison. */
            if (this.isWord('DISTINCT') && this.isWordAt(1, 'FROM')) {
                this.advance();
                this.advance();
                var fbDistinct = this.setFallback('IS DISTINCT FROM needs a value after it. Add a value or column');
                this.parseBitwiseOr(false);
                this.restoreFallback(fbDistinct);
                return true;
            };
            this.expectWord('NULL', 'IS must be followed by NULL or NOT NULL. Add NULL');
            return true;
        };
        var t = this.cur();
        if (t && t.type === 'operator' && STRICT_COMPARISON_OPS[t.value]) {
            this.advance();
            if (this.isWordAny(['ALL', 'ANY', 'SOME']) && this.isPunctAt(1, '(')) {
                this.advance();
                var openTok2 = this.advance();
                if (this.isWord('SELECT') || this.isWord('WITH')) {
                    this.parseStatementBody();
                } else {
                    var fb6 = this.setFallback('ALL, ANY and SOME need a subquery. Add SELECT');
                    this.parseOrExpr(false);
                    this.restoreFallback(fb6);
                };
                this.expectCloseParen(openTok2);
            } else {
                var fb7 = this.setFallback('This comparison is missing its right side. Add a value or column');
                this.parseBitwiseOr(false);
                this.restoreFallback(fb7);
            };
            return true;
        };
        return leftR.pure && leftR.bool;
    };
    /**
     * @method parseBitwiseOr
     * @description Parses a chain of one or more bitwise-XOR expressions joined by '|'.
     * @param {boolean} [isEnforced] - True when the leftmost operand must be predicate-shaped; propagated only to that operand.
     * @returns {Object} {pure, bool} describing whether only a single unmodified primary was consumed, and whether it is boolean-shaped.
     */
    StrictParser.prototype.parseBitwiseOr = function (isEnforced) {
        var r = this.parseBitwiseXor(isEnforced);
        var isPureOperand = r.pure, isBooleanShaped = r.bool;
        while (this.isOp('|')) {
            this.advance();
            this.parseBitwiseXor(false);
            isPureOperand = false;
            isBooleanShaped = false;
        };
        return {
            pure: isPureOperand,
            bool: isBooleanShaped
        };
    };
    /**
     * @method parseBitwiseXor
     * @description Parses a chain of one or more bitwise-AND expressions joined by '^'.
     * @param {boolean} [isEnforced] - True when the leftmost operand must be predicate-shaped; propagated only to that operand.
     * @returns {Object} {pure, bool}.
     */
    StrictParser.prototype.parseBitwiseXor = function (isEnforced) {
        var r = this.parseBitwiseAnd(isEnforced);
        var isPureOperand = r.pure, isBooleanShaped = r.bool;
        while (this.isOp('^')) {
            this.advance();
            this.parseBitwiseAnd(false);
            isPureOperand = false;
            isBooleanShaped = false;
        };
        return {
            pure: isPureOperand,
            bool: isBooleanShaped
        };
    };
    /**
     * @method parseBitwiseAnd
     * @description Parses a chain of one or more additive expressions joined by '&'.
     * @param {boolean} [isEnforced] - True when the leftmost operand must be predicate-shaped; propagated only to that operand.
     * @returns {Object} {pure, bool}.
     */
    StrictParser.prototype.parseBitwiseAnd = function (isEnforced) {
        var r = this.parseAdditive(isEnforced);
        var isPureOperand = r.pure, isBooleanShaped = r.bool;
        while (this.isOp('&')) {
            this.advance();
            this.parseAdditive(false);
            isPureOperand = false;
            isBooleanShaped = false;
        };
        return {
            pure: isPureOperand,
            bool: isBooleanShaped
        };
    };
    /**
     * @method parseAdditive
     * @description Parses a chain of one or more multiplicative expressions joined by '+', '-' or '||'.
     * @param {boolean} [isEnforced] - True when the leftmost operand must be predicate-shaped; propagated only to that operand.
     * @returns {Object} {pure, bool}.
     */
    StrictParser.prototype.parseAdditive = function (isEnforced) {
        var r = this.parseMultiplicative(isEnforced);
        var isPureOperand = r.pure, isBooleanShaped = r.bool;
        /* || is SQL Server 2025's string concatenation, parsed like + so that MCE074 can be the one to report it. */
        while (this.isOp('+') || this.isOp('-') || this.isOp('||')) {
            this.advance();
            this.parseMultiplicative(false);
            isPureOperand = false;
            isBooleanShaped = false;
        };
        return {
            pure: isPureOperand,
            bool: isBooleanShaped
        };
    };
    /**
     * @method parseMultiplicative
     * @description Parses a chain of one or more unary expressions joined by '*', '/' or '%'.
     * @param {boolean} [isEnforced] - True when the leftmost operand must be predicate-shaped; propagated only to that operand.
     * @returns {Object} {pure, bool}.
     */
    StrictParser.prototype.parseMultiplicative = function (isEnforced) {
        var r = this.parseUnary(isEnforced);
        var isPureOperand = r.pure, isBooleanShaped = r.bool;
        while (this.isOp('*') || this.isOp('/') || this.isOp('%')) {
            this.advance();
            this.parseUnary(false);
            isPureOperand = false;
            isBooleanShaped = false;
        };
        return {
            pure: isPureOperand,
            bool: isBooleanShaped
        };
    };
    /**
     * @method parseUnary
     * @description Parses an optional leading unary '-', '+' or '~' followed by another unary expression, or falls through to a postfix expression.
     * @param {boolean} [isEnforced] - True when this operand must be predicate-shaped; only meaningful when no unary sign is present.
     * @returns {Object} {pure, bool}.
     */
    StrictParser.prototype.parseUnary = function (isEnforced) {
        if (this.isOp('-') || this.isOp('+') || this.isOp('~')) { this.advance(); this.parseUnary(false); return {
            pure: false,
            bool: false
        }; }
        return this.parsePostfix(isEnforced);
    };
    /**
     * @method parsePostfix
     * @description Parses a primary expression followed by zero or more postfix modifiers, a COLLATE collation or an AT TIME ZONE value.
     * @param {boolean} [isEnforced] - True when this operand must be predicate-shaped; propagated to the primary expression.
     * @returns {Object} {pure, bool}.
     */
    StrictParser.prototype.parsePostfix = function (isEnforced) {
        var r = this.parsePrimary(isEnforced);
        var isPureOperand = r.pure, isBooleanShaped = r.bool;
        for (;;) {
            if (this.isWord('COLLATE')) {
                this.advance();
                var ct = this.cur();
                if (!ct || ct.type !== 'identifier') this.fail(ct, 'COLLATE needs a collation name. Add a collation name');
                this.advance();
                isPureOperand = false; isBooleanShaped = false;
                continue;
            };
            if (this.isWord('AT') && this.isWordAt(1, 'TIME') && this.isWordAt(2, 'ZONE')) {
                this.advance(); this.advance(); this.advance();
                var fb = this.setFallback('AT TIME ZONE needs a time zone value. Add a time zone');
                this.parseBitwiseOr(false);
                this.restoreFallback(fb);
                isPureOperand = false; isBooleanShaped = false;
                continue;
            };
            break;
        };
        return {
            pure: isPureOperand,
            bool: isBooleanShaped
        };
    };

    /**
     * @method parsePrimary
     * @description Parses one primary expression: a literal, variable, NULL, CASE, EXISTS, CAST/TRY_CAST, CONVERT/TRY_CONVERT, PARSE/TRY_PARSE, a parenthesized group or subquery, an identifier (column or function call), or one of the handful of built-in function names and niladic literals the tokenizer types as keywords.
     * @param {boolean} [isEnforced] - True when a parenthesized group is a condition position, so its own content is enforced the same way.
     * @returns {Object} {pure, bool}.
     */
    StrictParser.prototype.parsePrimary = function (isEnforced) {
        var t = this.cur();
        if (!t) { this.failExpected(this.exprFallback); return {
            pure: true,
            bool: false
        }; }

        if (t.type === 'number') { this.advance(); return {
            pure: true,
            bool: false
        }; }
        if (t.type === 'string') {
            if (t.unterminated) this.failBare(t, t, 'This string starting on line ' + t.line + ' is never closed. Add the missing closing quote.');
            this.advance();
            return {
                pure: true,
                bool: false
            };
        };
        if (t.type === 'variable') { this.advance(); return {
            pure: true,
            bool: false
        }; }
        if (this.isWord('NULL')) { this.advance(); return {
            pure: true,
            bool: false
        }; }
        if (this.isWord('CASE')) { this.parseCaseExpr(); return {
            pure: true,
            bool: false
        }; }
        if (this.isWord('EXISTS')) { this.parseExistsExpr(); return {
            pure: true,
            bool: true
        }; }
        if (this.isWord('CAST') || this.isWord('TRY_CAST')) { this.parseCastExpr(); return {
            pure: true,
            bool: false
        }; }
        if (this.isWord('CONVERT') || this.isWord('TRY_CONVERT')) { this.parseConvertExpr(); return {
            pure: true,
            bool: false
        }; }
        if (this.isWord('PARSE') || this.isWord('TRY_PARSE')) { this.parseParseExpr(); return {
            pure: true,
            bool: false
        }; }
        if (t.type === 'punct' && t.value === '(') return this.parseParenExpr(isEnforced);
        if (t.type === 'identifier') {
            var isCondition = this.parseIdentifierPrimary();
            return {
                pure: true,
                bool: isCondition
            };
        };
        // A handful of built-in function names (LEFT, RIGHT, COALESCE, NULLIF, ...)
        // and niladic literals (CURRENT_TIMESTAMP, SYSTEM_USER, ...) are also
        // T-SQL reserved words, so the tokenizer types them 'keyword'; match them
        // by spelling rather than widen the identifier check to any keyword.
        if (t.type === 'keyword' && STRICT_KEYWORD_FUNCTIONS[t.upper] && this.isPunctAt(1, '(')) { this.parseIdentifierPrimary(); return {
            pure: true,
            bool: false
        }; }
        if (t.type === 'keyword' && STRICT_KEYWORD_LITERALS[t.upper]) { this.advance(); return {
            pure: true,
            bool: false
        }; }

        this.failExpected(this.exprFallback);
        return {
            pure: true,
            bool: false
        };
    };

    // A parenthesised, non-subquery group: `isEnforced` carries through to its
    // content (the SAME position - condition or value - the group itself sits
    // in), so `(a = 1 OR b = 2)` used as a whole WHERE condition validates its
    // insides as a condition too, while `(a + b)` in a SELECT item stays a
    // plain, unenforced value grouping.
    /**
     * @method parseParenExpr
     * @description Parses a parenthesized group: either a subquery, SELECT/WITH, or a nested expression, propagating isEnforced into a non-subquery group's content since it sits in the same position as the group itself.
     * @param {boolean} [isEnforced] - True when the group is a condition position.
     * @returns {Object} {pure, bool}.
     */
    StrictParser.prototype.parseParenExpr = function (isEnforced) {
        var openTok = this.advance();
        var isBooleanShaped = false;
        if (this.isWord('SELECT') || this.isWord('WITH')) {
            this.parseStatementBody();
        } else {
            var contentStart = this.pos;
            var fb = this.setFallback('This ( is missing its content. Add a value or expression');
            // The content is parsed as a plain expression first: in a condition position a group
            // may be a condition, `(a = 1)`, or a value that an operator after the ) compares,
            // `(a + 1) > 2`. Which one it is only shows once the token after the ) is known.
            isBooleanShaped = this.parseOrExpr(false);
            if (isEnforced && !isBooleanShaped && !this.isValueContinuationAfterClose()) {
                // Neither a condition nor followed by an operator: parse it again as a condition,
                // so the error points at the offending operand inside the group.
                this.pos = contentStart;
                this._prevTok = openTok;
                isBooleanShaped = this.parseOrExpr(true);
            };
            this.restoreFallback(fb);
        };
        this.expectCloseParen(openTok);
        return {
            pure: true,
            bool: isBooleanShaped
        };
    };

    /**
     * @method isValueContinuationAfterClose
     * @description Tells whether the token after the current closing parenthesis continues the group
     *   as a value: a comparison, arithmetic or bitwise operator, or IS, BETWEEN, IN, LIKE, NOT,
     *   COLLATE or AT. Used so `(a + 1) > 2` in a condition position is read as a comparison.
     * @returns {boolean}
     */
    StrictParser.prototype.isValueContinuationAfterClose = function () {
        var next = this.pos + 1 < this.end ? this.tokens[this.pos + 1] : null;
        if (!next) return false;
        if (next.type === 'operator') return true;
        return next.type === 'keyword' && ['IS', 'BETWEEN', 'IN', 'LIKE', 'NOT', 'COLLATE', 'AT'].indexOf(next.upper) !== -1;
    };

    /**
     * @method parseIdentifierPrimary
     * @description Parses a dotted identifier chain, then, if it's immediately followed by '(', its call arguments and any WITHIN GROUP or OVER window clause.
     * @returns {boolean} True for REGEXP_LIKE(...), SQL Server 2025's yes-or-no condition, which stands where a condition does: in WHERE, ON, HAVING and CASE WHEN. Every other name or call is a value.
     */
    StrictParser.prototype.parseIdentifierPrimary = function () {
        var chainLast = this.advance();
        /* Only REGEXP_LIKE itself is a condition: x.REGEXP_LIKE(a) is a value, which MCE074 does not read as the 2025 function either
         * (the review after 1.2.0, 2026-10-09). */
        var isQualified = false;
        while (this.isPunct('.')) {
            isQualified = true;
            this.advance();
            var nt = this.cur();
            if (!nt || !(nt.type === 'identifier' || nt.type === 'number')) this.fail(nt, "A name is missing after '.'. Add the column or table name");
            chainLast = this.advance();
        };
        var isPredicateCall = false;
        if (this.isPunct('(')) {
            var openTok = this.advance();
            this.parseArgList(chainLast.upper);
            this.expectCloseParen(openTok);
            isPredicateCall = !isQualified && chainLast.upper === 'REGEXP_LIKE';
            if (this.isWord('WITHIN')) {
                this.advance();
                this.expectWord('GROUP', 'WITHIN needs GROUP after it. Add GROUP');
                if (!this.isPunct('(')) this.fail(this.cur(), 'WITHIN GROUP needs a parenthesized ORDER BY. Add (');
                var wOpen = this.advance();
                this.expectWord('ORDER', 'WITHIN GROUP needs an ORDER BY clause. Add ORDER BY');
                this.expectWord('BY', 'ORDER must be followed by BY. Add BY');
                this.parseOrderByList('ORDER BY needs a column or expression. Add a column or expression');
                this.expectCloseParen(wOpen);
            };
            if (this.isWord('OVER')) {
                this.advance();
                if (!this.isPunct('(')) this.fail(this.cur(), 'OVER needs a parenthesized window definition. Add (');
                var oOpen = this.advance();
                this.parseOverBody();
                this.expectCloseParen(oOpen);
                isPredicateCall = false;
            };
        };
        return isPredicateCall;
    };

    /**
     * @method parseArgList
     * @description Parses a function call's comma-separated argument list, allowing a bare '*', for COUNT(*), and an optional leading DISTINCT on the first argument. JSON_OBJECT and JSON_OBJECTAGG take key: value pairs, JSON_ARRAYAGG an ORDER BY after its value, and the JSON constructors a NULL ON NULL or ABSENT ON NULL clause. The six JSON functions of JSON_RETURNING_FUNCTIONS may end with SQL Server 2025's RETURNING and a type, which is read so that MCE074 and not MCE000 reports it.
     * @param {string} functionName - The called function's name in upper case.
     */
    StrictParser.prototype.parseArgList = function (functionName) {
        /* SQL Server 2022's JSON constructors, which run in a Query Activity (org check, 2026-09-28):
        JSON_OBJECT('key': value, ...) and JSON_ARRAY(value, ...), each with an optional closing
        NULL ON NULL or ABSENT ON NULL. JSON_OBJECTAGG(key: value) and JSON_ARRAYAGG(value) are SQL Server
        2025's aggregates, read the same way. */
        var isJsonObject = functionName === 'JSON_OBJECT' || functionName === 'JSON_OBJECTAGG';
        var isJsonConstructor = isJsonObject || functionName === 'JSON_ARRAY' || functionName === 'JSON_ARRAYAGG';
        var self = this;
        var skipNullClause = function () {
            if (!isJsonConstructor || !(self.isWord('NULL') || self.isWord('ABSENT')) || !self.isWordAt(1, 'ON') || !self.isWordAt(2, 'NULL')) return false;
            self.advance();
            self.advance();
            self.advance();
            return true;
        };
        /* RETURNING type, after the arguments. A missing type is an error: parseTypeName names it. */
        /* RETURNING is the clause with a data type after it. After the arguments, where no value can stand, it is the clause with a ) after
         * it too, which parseTypeName reports as a type missing; first in the call, JSON_ARRAY(Returning) is a field. */
        var isReturningClause = function (isAfterArguments) {
            var typeTok = self.at(1);
            if (!JSON_RETURNING_FUNCTIONS[functionName] || !self.isWord('RETURNING') || !typeTok) return false;
            if ((typeTok.type === 'identifier' || typeTok.type === 'keyword') && RETURNING_TYPES[typeTok.upper]) return true;
            return isAfterArguments && typeTok.type === 'punct' && typeTok.value === ')';
        };
        var skipReturning = function () {
            if (!isReturningClause(true)) return;
            self.advance();
            self.parseTypeName();
        };
        if (this.isPunct(')')) return;
        /* JSON_OBJECT(RETURNING JSON) has no arguments. A column named Returning is one unless a data type follows it. */
        if (isReturningClause(false)) {
            skipReturning();
            return;
        };
        if (skipNullClause()) {
            skipReturning();
            return;
        };
        /* TRIM([LEADING | TRAILING | BOTH] [characters FROM] string): the FROM form is SQL Server 2017,
        the direction words SQL Server 2022. A column named Leading, TRAILING(x) or both stays a column. */
        if (functionName === 'TRIM') {
            if (this.isWordAny(['LEADING', 'TRAILING', 'BOTH']) && !this.isPunctAt(1, ')') && !this.isPunctAt(1, ',')) this.advance();
            if (this.isWord('FROM')) this.advance();
            var fbTrim = this.setFallback('TRIM needs the text to trim. Add a value or column');
            this.parseOrExpr();
            this.restoreFallback(fbTrim);
            if (this.isWord('FROM')) {
                this.advance();
                var fbTrimFrom = this.setFallback('TRIM needs the text after FROM. Add a value or column');
                this.parseOrExpr();
                this.restoreFallback(fbTrimFrom);
            };
            return;
        };
        for (;;) {
            if (this.isOp('*') && this.isPunctAt(1, ')')) {
                this.advance();
            } else if (this.isWord('DISTINCT')) {
                this.advance();
                var fb1 = this.setFallback('DISTINCT needs an argument after it. Add an expression');
                this.parseOrExpr();
                this.restoreFallback(fb1);
            } else {
                var fb2 = this.setFallback('This function call is missing an argument. Add an argument or )');
                this.parseOrExpr();
                this.restoreFallback(fb2);
                var colon = this.cur();
                if (isJsonObject && colon && colon.value === ':') {
                    this.advance();
                    var fb3 = this.setFallback('This ' + functionName + ' key has no value after its colon. Add a value');
                    this.parseOrExpr();
                    this.restoreFallback(fb3);
                };
                if (functionName === 'JSON_ARRAYAGG' && this.isWord('ORDER') && this.isWordAt(1, 'BY')) {
                    this.advance();
                    this.advance();
                    this.parseOrderByList('ORDER BY needs a column or expression. Add a column or expression');
                };
            };
            if (skipNullClause()) break;
            if (this.isPunct(',')) {
                var argComma = this.advance();
                if (this.isPunct(')')) {
                    this.failWithFix(argComma, 'This argument list has a trailing comma before the closing parenthesis. Remove the trailing comma, near \')\'.',
                        { title: 'Remove trailing comma', edits: [{ start: argComma.start, end: argComma.end, text: '' }], isSafe: true, isInFixAll: true });
                };
                continue;
            };
            break;
        };
        skipReturning();
    };

    /**
     * @method parseOverBody
     * @description Parses the body of an OVER(...) window specification: an optional PARTITION BY list, an optional ORDER BY list, and an optional ROWS/RANGE frame clause.
     */
    StrictParser.prototype.parseOverBody = function () {
        if (this.isWord('PARTITION')) {
            this.advance();
            this.expectWord('BY', 'PARTITION must be followed by BY. Add BY');
            this.parseExprListReq('PARTITION BY needs a column or expression. Add a column or expression');
        };
        if (this.isWord('ORDER')) {
            this.advance();
            this.expectWord('BY', 'ORDER must be followed by BY. Add BY');
            this.parseOrderByList('ORDER BY needs a column or expression. Add a column or expression');
        };
        if (this.isWordAny(['ROWS', 'RANGE'])) {
            this.parseFrameClause();
        };
    };

    /**
     * @method parseFrameClause
     * @description Parses a window frame clause, either a single frame bound or a BETWEEN ... AND ... pair, after its ROWS or RANGE keyword.
     */
    StrictParser.prototype.parseFrameClause = function () {
        this.advance(); // ROWS or RANGE
        if (this.isWord('BETWEEN')) {
            this.advance();
            this.parseFrameBound();
            this.expectWord('AND', 'BETWEEN in a window frame needs AND. Add AND');
            this.parseFrameBound();
        } else {
            this.parseFrameBound();
        };
    };
    /**
     * @method parseFrameBound
     * @description Parses one window frame bound: UNBOUNDED PRECEDING/FOLLOWING, CURRENT ROW, or an expression followed by PRECEDING/FOLLOWING.
     */
    StrictParser.prototype.parseFrameBound = function () {
        if (this.isWord('UNBOUNDED')) {
            this.advance();
            if (this.isWordAny(['PRECEDING', 'FOLLOWING'])) {
                this.advance();
                return;
            };
            this.fail(this.cur(), 'UNBOUNDED needs PRECEDING or FOLLOWING after it. Add PRECEDING or FOLLOWING');
            return;
        };
        if (this.isWord('CURRENT')) {
            this.advance();
            this.expectWord('ROW', 'CURRENT must be followed by ROW. Add ROW');
            return;
        };
        var fb = this.setFallback('This window frame is missing a bound. Add a row count or UNBOUNDED');
        this.parseBitwiseOr();
        this.restoreFallback(fb);
        if (this.isWordAny(['PRECEDING', 'FOLLOWING'])) {
            this.advance();
            return;
        };
        this.fail(this.cur(), 'This frame bound needs PRECEDING or FOLLOWING. Add PRECEDING or FOLLOWING');
    };

    /**
     * @method parseCaseExpr
     * @description Parses a CASE expression, either simple, CASE operand WHEN value THEN, or searched, CASE WHEN condition THEN, requiring at least one WHEN and a closing END; a searched CASE's WHEN operands are enforced as conditions, a simple CASE's are not.
     */
    StrictParser.prototype.parseCaseExpr = function () {
        var caseTok = this.advance(); // CASE
        // Simple CASE (`CASE expr WHEN value THEN ...`) compares an operand to
        // each WHEN value, so those values are plain scalars; searched CASE
        // (`CASE WHEN condition THEN ...`, WHEN immediately after CASE) needs an
        // actual predicate in each WHEN, per the boolean-condition rule below.
        var isSearched = this.isWord('WHEN');
        if (!isSearched) {
            var fb0 = this.setFallback('CASE needs WHEN, or a value to compare before WHEN. Add WHEN or a value');
            this.parseOrExpr(false);
            this.restoreFallback(fb0);
        };
        var hasWhen = false;
        while (this.isWord('WHEN')) {
            hasWhen = true;
            this.advance();
            var fb1 = this.setFallback(isSearched ? 'WHEN needs a condition after it. Add a condition' : 'WHEN needs a value to compare after it. Add a value');
            this.parseOrExpr(isSearched);
            this.restoreFallback(fb1);
            this.expectWord('THEN', 'WHEN needs THEN after its condition. Add THEN');
            var fb2 = this.setFallback('THEN needs a result value. Add a value or expression');
            this.parseOrExpr(false);
            this.restoreFallback(fb2);
        };
        if (!hasWhen) this.fail(this.cur(), 'CASE needs at least one WHEN. Add WHEN');
        if (this.isWord('ELSE')) {
            this.advance();
            var fb3 = this.setFallback('ELSE needs a result value. Add a value or expression');
            this.parseOrExpr(false);
            this.restoreFallback(fb3);
        };
        if (!this.isWord('END')) {
            this.failBare(caseTok, this._prevTok || caseTok, 'This CASE starting on line ' + caseTok.line + ' is missing END. Add END to close it.');
        };
        this.advance(); // END
    };

    /**
     * @method parseExistsExpr
     * @description Parses an EXISTS(subquery) expression.
     */
    StrictParser.prototype.parseExistsExpr = function () {
        this.advance(); // EXISTS
        if (!this.isPunct('(')) this.fail(this.cur(), 'EXISTS needs a parenthesized subquery. Add (');
        var openTok = this.advance();
        if (this.isWord('SELECT') || this.isWord('WITH')) {
            this.parseStatementBody();
        } else {
            this.fail(this.cur(), 'EXISTS needs a SELECT inside its parentheses. Add SELECT');
        };
        this.expectCloseParen(openTok);
    };

    /**
     * @method parseCastExpr
     * @description Parses a CAST(expr AS type) or TRY_CAST(expr AS type) expression.
     */
    StrictParser.prototype.parseCastExpr = function () {
        this.advance(); // CAST or TRY_CAST
        if (!this.isPunct('(')) this.fail(this.cur(), 'CAST needs its argument in parentheses. Add (');
        var openTok = this.advance();
        var fb = this.setFallback('This ( is missing its content. Add a value or expression');
        this.parseOrExpr();
        this.restoreFallback(fb);
        this.expectWord('AS', 'CAST needs AS before the target type. Add AS');
        this.parseTypeName();
        this.expectCloseParen(openTok);
    };

    /**
     * @method parseConvertExpr
     * @description Parses a CONVERT(type, expr) or TRY_CONVERT(type, expr), with an optional style argument, expression.
     */
    StrictParser.prototype.parseConvertExpr = function () {
        this.advance(); // CONVERT or TRY_CONVERT
        if (!this.isPunct('(')) this.fail(this.cur(), 'CONVERT needs its arguments in parentheses. Add (');
        var openTok = this.advance();
        this.parseTypeName();
        if (!this.isPunct(',')) this.fail(this.cur(), 'CONVERT needs a comma after the type. Add ,');
        this.advance();
        var fb = this.setFallback('CONVERT needs the value to convert. Add a value or expression');
        this.parseOrExpr();
        if (this.isPunct(',')) {
            this.advance();
            this.parseOrExpr();
        };
        this.restoreFallback(fb);
        this.expectCloseParen(openTok);
    };

    // PARSE(value AS type [USING culture]) / TRY_PARSE(...): a different
    // argument grammar from a generic function call, so it gets its own path.
    /**
     * @method parseParseExpr
     * @description Parses a PARSE(value AS type) or TRY_PARSE(...) expression, with an optional USING culture clause, which has its own argument grammar distinct from a generic function call.
     */
    StrictParser.prototype.parseParseExpr = function () {
        this.advance(); // PARSE or TRY_PARSE
        if (!this.isPunct('(')) this.fail(this.cur(), 'PARSE needs its argument in parentheses. Add (');
        var openTok = this.advance();
        var fb = this.setFallback('This ( is missing its content. Add a value or expression');
        this.parseOrExpr();
        this.restoreFallback(fb);
        this.expectWord('AS', 'PARSE needs AS before the target type. Add AS');
        this.parseTypeName();
        if (this.isWord('USING')) {
            this.advance();
            var fb2 = this.setFallback('USING needs a culture value. Add a culture value');
            this.parseOrExpr();
            this.restoreFallback(fb2);
        };
        this.expectCloseParen(openTok);
    };

    // Consumes tokens up to (and including) the ')' matching an already-consumed
    // '(', without validating what is inside. Used for grammar corners that are
    // out of scope to model in full (OPENJSON's WITH (...) schema, PIVOT/UNPIVOT
    // bodies): permissive on purpose, so a well-formed but exotic query is never
    // flagged, while an actually unbalanced '(' is still caught.
    /**
     * @method skipBalancedParenContent
     * @description Consumes tokens up to and including the ')' that matches an already-consumed '(', without validating what is inside, for grammar corners, such as OPENJSON's WITH schema or PIVOT/UNPIVOT bodies, this parser deliberately doesn't model in full.
     * @param {Object} openTok - The already-consumed '(' token this content belongs to.
     */
    StrictParser.prototype.skipBalancedParenContent = function (openTok) {
        var depth = 1;
        for (;;) {
            var t = this.cur();
            if (!t) {
                this.failBare(openTok, openTok, 'This ( from line ' + openTok.line + ' is never closed. Add ) to close it, near the end of the query.');
                return;
            };
            if (t.type === 'punct' && t.value === '(') {
                depth++;
                this.advance();
                continue;
            };
            if (t.type === 'punct' && t.value === ')') {
                this.advance();
                depth--;
                if (depth === 0) return;
                continue;
            };
            this.advance();
        };
    };

    /**
     * @method parseTypeName
     * @description Parses a data type name, optionally followed by a length or MAX, or a precision and scale, in parentheses.
     */
    StrictParser.prototype.parseTypeName = function () {
        var t = this.cur();
        /* A type name the tokenizer marks as a keyword, as TIME in CAST(x AS TIME), is a type too: as first built it failed with MCE000
         * (the second review after 1.2.0, 2026-10-09). */
        if (!t || !(t.type === 'identifier' || (t.type === 'keyword' && RETURNING_TYPES[t.upper]))) this.fail(t, 'A data type is missing here. Add a data type such as VARCHAR or INT');
        this.advance();
        if (this.isPunct('(')) {
            var openTok = this.advance();
            if (this.isWord('MAX')) {
                this.advance();
            } else {
                var nt = this.cur();
                if (!nt || nt.type !== 'number') this.fail(nt, 'This type needs a length, precision or MAX. Add a number or MAX');
                this.advance();
                if (this.isPunct(',')) {
                    this.advance();
                    var st = this.cur();
                    if (!st || st.type !== 'number') this.fail(st, 'This type needs a scale after the comma. Add a number');
                    this.advance();
                };
            };
            this.expectCloseParen(openTok);
        };
    };

    // ---- expression-list helpers ------------------------------------------
    /**
     * @method isListTerminator
     * @description Tests whether the current token would end a comma-separated list here rather than start another item: end of input, a closing parenthesis, a statement-ending ';', or a clause boundary keyword such as FROM, WHERE, GROUP BY, ORDER BY, HAVING or a set operator. Used right after consuming a comma to detect a trailing comma.
     * @returns {boolean} True when the current token ends the list.
     */
    StrictParser.prototype.isListTerminator = function () {
        var t = this.cur();
        if (!t) return true;
        if (t.type === 'punct' && (t.value === ')' || t.value === ';')) return true;
        return isBoundaryKeyword(t, this.at(1));
    };
    /**
     * @method failTrailingListComma
     * @description Throws the MCE000 "trailing comma in a list" error at the given comma token, with a fix that deletes it.
     * @param {Object} commaTok - The trailing comma token.
     */
    StrictParser.prototype.failTrailingListComma = function (commaTok) {
        this.failWithFix(commaTok, 'This list has a trailing comma. Remove the trailing comma, near \',\'.',
            { title: 'Remove trailing comma', edits: [{ start: commaTok.start, end: commaTok.end, text: '' }], isSafe: true, isInFixAll: true });
    };
    /**
     * @method parseExprListReq
     * @description Parses one or more comma-separated expressions, using fallbackHint as the missing-expression message for this position.
     * @param {string} fallbackHint - Hint to show if an expression is missing here.
     */
    StrictParser.prototype.parseExprListReq = function (fallbackHint) {
        var fb = this.setFallback(fallbackHint);
        this.parseOrExpr();
        while (this.isPunct(',')) {
            var listComma = this.advance();
            if (this.isListTerminator()) {
                this.restoreFallback(fb);
                this.failTrailingListComma(listComma);
            };
            this.parseOrExpr();
        };
        this.restoreFallback(fb);
    };
    /**
     * @method parseOrderByList
     * @description Parses a comma-separated ORDER BY list, each item an expression with an optional ASC or DESC.
     * @param {string} [fallbackHint] - Hint to show if an expression is missing here.
     */
    StrictParser.prototype.parseOrderByList = function (fallbackHint) {
        var fb = this.setFallback(fallbackHint || 'ORDER BY needs a column or expression. Add a column or expression');
        this.parseOrExpr();
        if (this.isWordAny(['ASC', 'DESC'])) this.advance();
        while (this.isPunct(',')) {
            var listComma = this.advance();
            if (this.isListTerminator()) {
                this.restoreFallback(fb);
                this.failTrailingListComma(listComma);
            };
            this.parseOrExpr();
            if (this.isWordAny(['ASC', 'DESC'])) this.advance();
        };
        this.restoreFallback(fb);
    };

    // ---- select list --------------------------------------------------------
    /**
     * @method parseSelectItem
     * @description Parses one select-list item: '*', 'alias.*', an alias equals expr assignment, or an expression with an optional AS alias or implicit alias.
     */
    StrictParser.prototype.parseSelectItem = function () {
        // '*' or 'alias.*'
        if (this.isOp('*')) {
            this.advance();
            return;
        };
        if (this.cur() && this.cur().type === 'identifier' && this.isPunctAt(1, '.') &&
            this.at(2) && this.at(2).type === 'operator' && this.at(2).value === '*') {
            this.advance(); this.advance(); this.advance();
            return;
        };
        // 'alias = expr', or a string literal alias: 'Total' = expr
        if (this.cur() && (this.cur().type === 'identifier' || this.cur().type === 'string') && this.at(1) && this.at(1).type === 'operator' && this.at(1).value === '=') {
            this.advance(); // alias name
            this.advance(); // '='
            var fb = this.setFallback("This alias assignment is missing its value after '='. Add an expression");
            this.parseOrExpr();
            this.restoreFallback(fb);
            return;
        };
        this.parseOrExpr();
        if (this.isWord('AS')) {
            this.advance();
            var t = this.cur();
            /* T-SQL also accepts a string literal as a column alias: AS 'Email Address'. */
            if (!t || !(t.type === 'identifier' || t.type === 'keyword' || (t.type === 'string' && !t.unterminated))) this.fail(t, 'AS needs an alias name after it. Add an alias');
            this.advance();
        } else {
            var t2 = this.cur();
            if (t2 && t2.type === 'identifier') this.advance();
        };
    };

    /**
     * @method parseSelectList
     * @description Parses a comma-separated select list, rejecting two commas in a row, which would leave an empty column.
     */
    StrictParser.prototype.parseSelectList = function () {
        this.parseSelectItem();
        while (this.isPunct(',')) {
            this.advance();
            if (this.isPunct(',')) {
                var secondComma = this.cur();
                this.failWithFix(secondComma, 'Two commas in a row leave an empty column here. Remove the extra comma, near \',\'.',
                    { title: 'Remove extra comma', edits: [{ start: secondComma.start, end: secondComma.end, text: '' }], isSafe: true, isInFixAll: true });
            };
            this.parseSelectItem();
        };
    };

    // ---- FROM / JOIN / table sources -----------------------------------------
    /**
     * @method parseTableSource
     * @description Parses one FROM/JOIN table source: a derived table subquery with an alias, or a possibly dotted, possibly table-valued-function-call, table name with an optional alias and table hints.
     * @param {string} afterText - Description of what precedes this table source, e.g. FROM or INNER JOIN, used in its error messages.
     */
    StrictParser.prototype.parseTableSource = function (afterText) {
        if (this.isPunct('(')) {
            var openTok = this.advance();
            if (this.isWord('SELECT') || this.isWord('WITH')) {
                this.parseStatementBody();
            } else if (this.isWord('VALUES')) {
                this.parseValuesRows();
            } else {
                this.fail(this.cur(), 'A derived table needs a SELECT inside its parentheses. Add SELECT');
            };
            this.expectCloseParen(openTok);
            if (this.isWord('AS')) this.advance();
            var t = this.cur();
            if (t && t.type === 'identifier') {
                this.advance();
                if (this.isPunct('(')) this.parseColumnAliasList();
            };
            return;
        };
        var nt = this.cur();
        if (!nt || !(nt.type === 'identifier' || nt.type === 'number')) {
            this.fail(nt, afterText + ' needs a table name after it. Add a table or Data Extension name');
        };
        this.advance();
        while (this.isPunct('.')) {
            this.advance();
            var dt = this.cur();
            if (!dt || !(dt.type === 'identifier' || dt.type === 'number')) this.fail(dt, "A name is missing after '.'. Add the column or table name");
            this.advance();
        };
        if (this.isPunct('(')) {
            // A table-valued function call used directly as a table source, e.g.
            // CROSS APPLY STRING_SPLIT(s.Tags, ',') or FROM OPENJSON(x).
            var fOpen = this.advance();
            this.parseArgList();
            this.expectCloseParen(fOpen);
            if (this.isWord('WITH') && this.isPunctAt(1, '(')) {
                this.advance();
                var wOpen = this.advance();
                this.skipBalancedParenContent(wOpen);
            };
        };
        var hasAlias = false;
        if (this.isWord('AS')) {
            this.advance();
            var at = this.cur();
            if (!at || at.type !== 'identifier') this.fail(at, 'AS needs a table alias after it. Add an alias');
            this.advance();
            hasAlias = true;
        } else {
            var at2 = this.cur();
            if (at2 && at2.type === 'identifier') {
                this.advance();
                hasAlias = true;
            };
        };
        // The older hint form without WITH, still accepted by SQL Server: FROM T t (NOLOCK).
        if (hasAlias && this.isPunct('(')) {
            var oldHintOpen = this.advance();
            this.parseTableHintList();
            this.expectCloseParen(oldHintOpen);
        };
        // Table hints: WITH (NOLOCK), WITH (INDEX(ix1), NOLOCK), ...
        if (this.isWord('WITH') && this.isPunctAt(1, '(')) {
            this.advance();
            var hOpen = this.advance();
            this.parseTableHintList();
            this.expectCloseParen(hOpen);
        };
    };

    /**
     * @method parseValuesRows
     * @description Parses a table value constructor's rows after VALUES, one or more comma-separated parenthesized expression lists: (VALUES (1, 'a'), (2, 'b')) AS v(n, s).
     */
    StrictParser.prototype.parseValuesRows = function () {
        this.advance(); // VALUES
        for (;;) {
            if (!this.isPunct('(')) this.fail(this.cur(), 'VALUES needs each row in parentheses. Add (');
            var rowOpen = this.advance();
            this.parseExprListReq('This VALUES row is missing a value. Add a value');
            this.expectCloseParen(rowOpen);
            if (this.isPunct(',')) {
                this.advance();
                continue;
            };
            break;
        };
    };

    /**
     * @method parseColumnAliasList
     * @description Parses the column alias list after a derived table's or VALUES constructor's alias, the (a, b) in AS x(a, b).
     */
    StrictParser.prototype.parseColumnAliasList = function () {
        var listOpen = this.advance(); // (
        for (;;) {
            var ct = this.cur();
            if (!ct || ct.type !== 'identifier') this.fail(ct, 'This column list is missing a name. Add a column name');
            this.advance();
            if (this.isPunct(',')) {
                this.advance();
                continue;
            };
            break;
        };
        this.expectCloseParen(listOpen);
    };

    /**
     * @method parseTableHintList
     * @description Parses a comma-separated table hint list inside WITH (...), e.g. NOLOCK or INDEX(ix1).
     */
    StrictParser.prototype.parseTableHintList = function () {
        for (;;) {
            if (this.isWord('INDEX') && this.isPunctAt(1, '(')) {
                this.advance();
                var openTok = this.advance();
                this.skipBalancedParenContent(openTok);
            } else {
                var t = this.cur();
                if (!t || !(t.type === 'identifier' || t.type === 'keyword')) this.fail(t, 'This table hint is missing its name. Add a hint such as NOLOCK');
                this.advance();
            };
            if (this.isPunct(',')) {
                this.advance();
                continue;
            };
            break;
        };
    };

    /**
     * @method isJoinStart
     * @description Tests whether the current token starts a join qualifier or a JOIN/APPLY keyword.
     * @returns {boolean} True when the current token can start a join.
     */
    StrictParser.prototype.isJoinStart = function () {
        return this.isWordAny(['INNER', 'LEFT', 'RIGHT', 'FULL', 'OUTER', 'CROSS', 'JOIN', 'APPLY']);
    };

    // PIVOT (...) AS alias / UNPIVOT (...) AS alias: parsed permissively (see
    // skipBalancedParenContent) since the FOR/IN sub-grammar is out of scope.
    /**
     * @method parsePivotOrUnpivotOpt
     * @description Parses an optional PIVOT(...) or UNPIVOT(...) suffix, with its alias, on a table source, skipping its body permissively since the FOR/IN sub-grammar is out of scope for this parser.
     */
    StrictParser.prototype.parsePivotOrUnpivotOpt = function () {
        if (!(this.isWord('PIVOT') || this.isWord('UNPIVOT'))) return;
        this.advance();
        if (!this.isPunct('(')) this.fail(this.cur(), 'PIVOT and UNPIVOT need their body in parentheses. Add (');
        var openTok = this.advance();
        this.skipBalancedParenContent(openTok);
        if (this.isWord('AS')) this.advance();
        var t = this.cur();
        if (t && t.type === 'identifier') this.advance();
    };

    // A single table source's own JOIN/APPLY chain (0 or more).
    /**
     * @method parseJoinChain
     * @description Parses zero or more JOIN/APPLY clauses following a table source, each with its qualifiers, INNER/LEFT/RIGHT/FULL/OUTER/CROSS, its own table source, and, unless it's a CROSS join or APPLY, a required ON condition.
     */
    StrictParser.prototype.parseJoinChain = function () {
        while (this.isJoinStart()) {
            var qualifiers = [];
            while (this.isWordAny(['INNER', 'LEFT', 'RIGHT', 'FULL', 'OUTER', 'CROSS'])) {
                qualifiers.push(this.advance().upper);
            };
            var kind;
            if (this.isWord('JOIN')) {
                this.advance();
                kind = 'JOIN';
            } else if (this.isWord('APPLY')) {
                this.advance();
                kind = 'APPLY';
            } else {
                this.fail(this.cur(), qualifiers.join(' ') + ' needs JOIN or APPLY after it. Add JOIN or APPLY');
                return;
            };
            var text = qualifiers.length ? (qualifiers.join(' ') + ' ' + kind) : kind;
            this.parseTableSource(text);
            var doesRequireOn = kind === 'JOIN' && qualifiers.indexOf('CROSS') === -1;
            if (doesRequireOn) {
                if (!this.isWord('ON')) {
                    var onTok = this.cur();
                    this.fail(onTok, text + ' needs an ON condition before ' + strictNearDesc(onTok) + '. Add ON with the join condition');
                };
                this.advance();
                var fb = this.setFallback('ON needs a join condition. Add a condition such as a.Key = b.Key');
                this.parseOrExpr(true);
                this.restoreFallback(fb);
            };
        };
    };

    // FROM table-source { , table-source }: implicit (comma) joins, each with
    // its own alias, hints, derived table and JOIN/APPLY chain.
    /**
     * @method parseFromClause
     * @description Parses a FROM clause: one table source, with its own PIVOT/UNPIVOT and JOIN/APPLY chain, followed by zero or more comma-separated additional table sources, each with the same suffixes.
     */
    StrictParser.prototype.parseFromClause = function () {
        this.parseTableSource('FROM');
        this.parsePivotOrUnpivotOpt();
        this.parseJoinChain();
        while (this.isPunct(',')) {
            this.advance();
            this.parseTableSource('FROM');
            this.parsePivotOrUnpivotOpt();
            this.parseJoinChain();
        };
    };

    // ---- SELECT statement / WITH / set operators -----------------------------
    /**
     * @method parseSelectStatement
     * @description Parses one SELECT statement: SELECT, with optional DISTINCT/ALL and TOP, the select list, and the optional FROM/WHERE/GROUP BY/HAVING/ORDER BY/OFFSET-FETCH/FOR XML clauses that may follow it.
     */
    StrictParser.prototype.parseSelectStatement = function () {
        if (!this.isWord('SELECT')) this.fail(this.cur(), 'This query is missing SELECT. Add SELECT');
        this.advance();
        if (this.isWordAny(['DISTINCT', 'ALL'])) this.advance();
        if (this.isWord('TOP')) {
            this.advance();
            if (this.isPunct('(')) {
                var openTok = this.advance();
                var fb1 = this.setFallback('TOP ( needs a number of rows. Add a number');
                this.parseOrExpr();
                this.restoreFallback(fb1);
                this.expectCloseParen(openTok);
            } else {
                var fb2 = this.setFallback('TOP needs a number of rows. Add a number');
                this.parseUnary();
                this.restoreFallback(fb2);
            };
            if (this.isWord('PERCENT')) this.advance();
            if (this.isWord('WITH') && this.isWordAt(1, 'TIES')) {
                this.advance();
                this.advance();
            };
        };

        var fbList = this.setFallback('The select list is missing a column or expression. Add a column or expression');
        this.parseSelectList();
        this.restoreFallback(fbList);

        if (this.isWord('FROM')) {
            this.advance();
            this.parseFromClause();
        };
        if (this.isWord('WHERE')) {
            this.advance();
            var fb3 = this.setFallback('WHERE needs a condition. Add a condition');
            this.parseOrExpr(true);
            this.restoreFallback(fb3);
        };
        if (this.isWord('GROUP')) {
            this.advance();
            this.expectWord('BY', 'GROUP must be followed by BY. Add BY');
            this.parseExprListReq('GROUP BY needs a column or expression. Add a column or expression');
        };
        if (this.isWord('HAVING')) {
            this.advance();
            var fb4 = this.setFallback('HAVING needs a condition. Add a condition');
            this.parseOrExpr(true);
            this.restoreFallback(fb4);
        };
        if (this.isWord('ORDER')) {
            this.advance();
            this.expectWord('BY', 'ORDER must be followed by BY. Add BY');
            this.parseOrderByList('ORDER BY needs a column or expression. Add a column or expression');
        };
        if (this.isWord('OFFSET')) {
            this.advance();
            var fb5 = this.setFallback('OFFSET needs a number of rows to skip. Add a number');
            this.parseUnary();
            this.restoreFallback(fb5);
            this.expectWord('ROWS', 'OFFSET needs ROWS after the number. Add ROWS');
            if (this.isWord('FETCH')) {
                this.advance();
                this.expectWord('NEXT', 'FETCH needs NEXT after it. Add NEXT');
                var fb6 = this.setFallback('FETCH NEXT needs a row count. Add a number');
                this.parseUnary();
                this.restoreFallback(fb6);
                this.expectWord('ROWS', 'FETCH NEXT needs ROWS after the number. Add ROWS');
                this.expectWord('ONLY', 'FETCH NEXT ... ROWS needs ONLY at the end. Add ONLY');
            };
        };
        this.parseForXmlOpt();
    };

    // FOR XML PATH[('name')] | RAW[('name')] | AUTO | EXPLICIT, optionally
    // followed by any of , TYPE / , ROOT('x') / , ELEMENTS. Allowed after the
    // last clause of any query or subquery (parseSelectStatement is that one
    // place, reached from the top-level statement, a derived table, EXISTS/IN/
    // scalar subqueries and CTE bodies alike, since they all funnel through
    // here via parseStatementBody).
    /**
     * @method parseForXmlOpt
     * @description Parses an optional trailing FOR XML clause, PATH or RAW with an optional name, AUTO or EXPLICIT, with optional TYPE, ROOT or ELEMENTS options, valid after the last clause of any SELECT reached through parseStatementBody.
     */
    StrictParser.prototype.parseForXmlOpt = function () {
        /* FOR JSON PATH | AUTO, then any of , ROOT[('name')] / , INCLUDE_NULL_VALUES /
        , WITHOUT_ARRAY_WRAPPER. The org's check passed FOR JSON PATH (2026-09-28). */
        if (this.isWord('FOR') && this.isWordAt(1, 'JSON')) {
            this.advance(); this.advance(); // FOR JSON
            if (this.isWordAny(['PATH', 'AUTO'])) this.advance();
            else this.fail(this.cur(), 'FOR JSON needs a mode. Add PATH or AUTO');
            while (this.isPunct(',')) {
                this.advance();
                if (this.isWordAny(['INCLUDE_NULL_VALUES', 'WITHOUT_ARRAY_WRAPPER'])) {
                    this.advance();
                } else if (this.isWord('ROOT')) {
                    this.advance();
                    if (this.isPunct('(')) {
                        var jOpen = this.advance();
                        if (this.cur() && this.cur().type === 'string') this.advance();
                        this.expectCloseParen(jOpen);
                    };
                } else {
                    this.fail(this.cur(), 'This FOR JSON option is not recognized. Add ROOT, INCLUDE_NULL_VALUES or WITHOUT_ARRAY_WRAPPER');
                };
            };
            return;
        };
        if (!(this.isWord('FOR') && this.isWordAt(1, 'XML'))) return;
        this.advance(); this.advance(); // FOR XML
        if (this.isWordAny(['PATH', 'RAW'])) {
            this.advance();
            if (this.isPunct('(')) {
                var openTok = this.advance();
                var nameTok = this.cur();
                if (nameTok && nameTok.type === 'string') this.advance();
                this.expectCloseParen(openTok);
            };
        } else if (this.isWordAny(['AUTO', 'EXPLICIT'])) {
            this.advance();
        } else {
            this.fail(this.cur(), 'FOR XML needs a mode. Add PATH, RAW, AUTO or EXPLICIT');
        };
        while (this.isPunct(',')) {
            this.advance();
            if (this.isWord('TYPE') || this.isWord('ELEMENTS')) {
                this.advance();
            } else if (this.isWord('ROOT')) {
                this.advance();
                if (!this.isPunct('(')) this.fail(this.cur(), 'ROOT needs its element name in parentheses. Add (');
                var rOpen = this.advance();
                var rTok = this.cur();
                if (rTok && rTok.type === 'string') this.advance();
                this.expectCloseParen(rOpen);
            } else {
                this.fail(this.cur(), 'This FOR XML option is not recognized. Add TYPE, ROOT(...) or ELEMENTS');
            };
        };
    };

    /**
     * @method parseSetOpTail
     * @description Parses zero or more UNION (ALL), EXCEPT or INTERSECT branches following a SELECT statement, each branch itself a full SELECT statement.
     */
    StrictParser.prototype.parseSetOpTail = function () {
        while (this.isWordAny(['UNION', 'EXCEPT', 'INTERSECT'])) {
            this.advance();
            if (this.isWord('ALL')) this.advance();
            this.parseSelectStatement();
        };
    };

    /**
     * @method parseOptionalWith
     * @description Parses an optional leading WITH clause defining one or more common table expressions, each with a name, an optional explicit column list, and a parenthesized body.
     */
    StrictParser.prototype.parseOptionalWith = function () {
        if (!this.isWord('WITH')) return;
        this.advance();
        for (;;) {
            var nameTok = this.cur();
            if (!nameTok || nameTok.type !== 'identifier') {
                this.fail(nameTok, 'WITH needs a name for this common table expression. Add a name');
            };
            this.advance();
            if (this.isPunct('(')) {
                var colOpen = this.advance();
                var ct = this.cur();
                if (!ct || ct.type !== 'identifier') this.fail(ct, 'This column list is missing a name. Add a column name');
                this.advance();
                while (this.isPunct(',')) {
                    this.advance();
                    var ct2 = this.cur();
                    if (!ct2 || ct2.type !== 'identifier') this.fail(ct2, 'This column list is missing a name. Add a column name');
                    this.advance();
                };
                this.expectCloseParen(colOpen);
            };
            this.expectWord('AS', 'This common table expression needs AS after its name. Add AS');
            if (!this.isPunct('(')) this.fail(this.cur(), 'AS needs the common table expression body in parentheses. Add (');
            var openTok = this.advance();
            this.parseOptionalWith();
            this.parseSelectStatement();
            this.parseSetOpTail();
            this.expectCloseParen(openTok);
            if (this.isPunct(',')) {
                this.advance();
                continue;
            };
            break;
        };
    };

    /**
     * @method parseStatementBody
     * @description Parses one full statement body: an optional WITH clause, a SELECT statement, and any trailing UNION/EXCEPT/INTERSECT branches. The single entry point every subquery, derived table, EXISTS/IN body and CTE body funnels through.
     */
    StrictParser.prototype.parseStatementBody = function () {
        this.parseOptionalWith();
        this.parseSelectStatement();
        this.parseSetOpTail();
    };

    // ---- per-statement driver -------------------------------------------------
    /**
     * @function strictParseStatement
     * @description Runs the strict parser over one top-level, ';'-separated, statement's tokens, first checking for an unterminated string, then catching any StrictError the parser throws and converting it into a single error object; never throws itself.
     * @param {Array<Object>} tokens - Comment-stripped token stream.
     * @param {number} start - Index of the statement's first token.
     * @param {number} end - Index just past the statement's last token.
     * @param {Array<number>} lineIndex - Line-start offsets, as built by buildLineIndex.
     * @returns {Object} The first syntax error found in this statement, or null.
     */
    function strictParseStatement(tokens, start, end, lineIndex) {
        if (end <= start) return null;
        for (var i = start; i < end; i++) {
            if (tokens[i].unterminated && tokens[i].type === 'string') {
                return strictMkErr(lineIndex, tokens[i], tokens[i], 'This string starting on line ' + tokens[i].line + ' is never closed. Add the missing closing quote.', '');
            };
        };
        var p = new StrictParser(tokens, start, end, null, lineIndex);
        try {
            p.parseStatementBody();
            if (p.pos < p.end) {
                p.fail(p.cur(), 'There is extra text after the end of the query. Remove it');
            };
            return null;
        } catch (e) {
            if (e instanceof StrictError) return e.err;
            return null; // defensive: parseStrict must never throw or leak an error shape we didn't build
        };
    };

    // Shared by parseStrict(sql) and lint()'s per-call cache (ctx.getStrict),
    // which passes in the already-computed raw token list instead of having
    // parseStrict call tokenize() again (see L4). allTokens is the raw
    // tokenize() output (comments included, filtered out below), exactly what
    // parseStrict(sql) itself would compute.
    /**
     * @function parseStrictFromTokens
     * @description Runs the strict parser over an already-tokenized SQL string, splitting it into top-level, ';'-separated, statements and collecting at most one error per statement. Shared by parseStrict() and lint()'s memoized ctx.getStrict() so a query is never re-tokenized just to be re-parsed strictly.
     * @param {Array<Object>} allTokens - Raw tokenize() output, comments included and filtered out here.
     * @param {string} sql - Full SQL source text, used to build the line index.
     * @returns {Object} {errors}; one strict-parser error per offending statement.
     */
    function parseStrictFromTokens(allTokens, sql) {
        var errors = [];
        try {
            var tokens = allTokens.filter(function (t) { return t.type !== 'comment'; });
            var lineIndex = buildLineIndex(sql);
            var segStart = 0;
            for (var i = 0; i < tokens.length; i++) {
                if (tokens[i].depth === 0 && tokens[i].type === 'punct' && tokens[i].value === ';') {
                    var err = strictParseStatement(tokens, segStart, i, lineIndex);
                    if (err) errors.push(err);
                    segStart = i + 1;
                };
            };
            var lastErr = strictParseStatement(tokens, segStart, tokens.length, lineIndex);
            if (lastErr) errors.push(lastErr);
        } catch (e) { /* never throw */ }
        return { errors: errors };
    };

    /**
     * @function parseStrict
     * @description Tokenizes SQL text and runs the strict parser over it to find syntax errors MCE would reject on Run.
     * @param {string} sql - SQL text to check.
     * @returns {Object} {errors}, as returned by parseStrictFromTokens, or an empty errors array if tokenization itself fails.
     */
    function parseStrict(sql) {
        sql = sql == null ? '' : String(sql);
        var allTokens;
        try {
            allTokens = tokenize(sql);
        } catch (e) {
            return { errors: [] };
        };
        return parseStrictFromTokens(allTokens, sql);
    };

    // ---- MCE000 registration ---------------------------------------------
    // Pushed onto the already-built RULES array (rather than edited inline)
    // so every existing rule function above is left untouched.
    /* The strict parser stops at a statement's first syntax problem. A dangling AND or OR is reported on
    its own, each one, with a fix that removes it, and the strict error it would also cause, at the word
    after it, or at a leading one itself, gives way to it. */
    RULES.push(function ruleMCE000(sql, tokens, ctx) {
        var findings = [];
        var connectors = danglingConnectors(sql, tokens, ctx.getCoreTokens());
        var result = ctx.getStrict();
        /* A trailing connector's strict error is at the word after it, or at the connector itself when the parser had ended the
        statement before it, as after FROM Customers AS c WITH (NOLOCK): one problem, one row. */
        (result.errors || []).forEach(function (e) {
            var isConnectorError = connectors.some(function (c) {
                return c.isLeading ? e.start === c.token.start : (e.start >= c.token.start && e.start <= c.nextStart);
            });
            if (isConnectorError) return;
            findings.push(['MCE000', 'error', e.message, STRICT_DOCS_URL, e, e, e.fix ? [e.fix] : undefined]);
        });
        connectors.forEach(function (c) {
            var word = c.token.upper;
            var message = c.isLeading ?
                'This ' + word + ' has no condition before it. Remove the ' + word + ', or add the condition it joins.' :
                'This ' + word + ' has no condition after it. Add the condition, or remove the ' + word + '.';
            findings.push(['MCE000', 'error', message, STRICT_DOCS_URL, c.token, c.token, [
                { title: 'Remove ' + word, edits: [removeConnectorEdit(sql, tokens, c.token)], isSafe: true, isInFixAll: true }
            ]]);
        });
        return findings;
    });

    // ==================================================================
    // fixAll(sql, context)
    // ==================================================================
    var FIX_ALL_MAX_ROUNDS = 50;

    /**
     * @function shiftedOffset
     * @description Moves an offset of a text past a set of edits made to it, so a finding of the text before the edits can be found again in the text after them. An edit that ends at or before the offset moves it by the length it adds or takes away, unless it starts at the offset and replaces text there, as a rename of the finding's own first word does.
     * @param {number} offset - The offset in the text before the edits.
     * @param {Array<Object>} edits - Non-overlapping {start, end, text} edits of that text.
     * @returns {number} The offset in the text after the edits.
     */
    function shiftedOffset(offset, edits) {
        var shift = 0;
        edits.forEach(function (e) {
            if (e.end > offset || (e.start === offset && e.end > e.start)) return;
            shift += e.text.length - (e.end - e.start);
        });
        return offset + shift;
    };

    /**
     * @function fixAll
     * @description Repeatedly lints sql and applies the first finding's safe, Fix-all-eligible fix, until no such fix remains or FIX_ALL_MAX_ROUNDS rounds have run, so results-changing fixes (isSafe: false) and fixes marked isInFixAll: false, such as MCE009's and MCE013's, are never applied here even though some are otherwise safe. A fix whose result has more parseStrict errors than the text it was applied to is skipped, so Fix all can never make a query invalid. Idempotent: running it again on its own output applies nothing more. Each finding of the first lint is followed through the edits by its rule and its start (shiftedOffset), so the answer tells the findings the fixes uncovered apart. With options.isFoundOnly, only the fixes of the first lint's findings are applied, the ones the Frontend's "Fix all (N)" counts, and a finding a fix uncovers is left for the user to see.
     * @param {string} sql - SQL text to fix.
     * @param {Object} context - Same shape lint() takes: {schema, targetKey, options: {disabled}}.
     * @param {Object} [options] - {isFoundOnly}: true to apply only the fixes of the findings the first lint gives.
     * @returns {Object} {sql, appliedCount, appliedIds, newCount}: the fixed text, how many fixes were applied, each applied fix's rule id in order, and how many findings of the fixed text the first lint did not give.
     */
    function fixAll(sql, context, options) {
        var current = sql == null ? '' : String(sql);
        var isFoundOnly = !!(options && options.isFoundOnly);
        var appliedCount = 0;
        var appliedIds = [];
        /* Safety net: a fix whose result has more parseStrict errors than the
        text it was applied to is never applied, so one wrong fix cannot turn
        a runnable query into one Marketing Cloud Engagement rejects. */
        var rejected = {};
        var currentErrors = null;
        /* The first lint's findings, by rule and start, moved past every edit applied since. */
        var found = null;
        var findings = null;
        /**
         * @function foundIndex
         * @description Finds a finding among the first lint's findings that are still open.
         * @param {Object} finding - A finding of the current text.
         * @returns {number} Its index in found, or -1 for a finding the fixes uncovered.
         */
        function foundIndex(finding) {
            for (var k = 0; k < found.length; k++) {
                if (found[k].id === finding.id && found[k].start === finding.start) return k;
            };
            return -1;
        };
        for (var round = 0; round < FIX_ALL_MAX_ROUNDS; round++) {
            findings = lint(current, context);
            if (!found) {
                found = findings.map(function (f) {
                    return {
                        id: f.id,
                        start: f.start
                    };
                });
            };
            var target = null;
            for (var i = 0; i < findings.length; i++) {
                var candidate = findings[i].fixes && findings[i].fixes[0];
                if (!(candidate && candidate.isSafe && candidate.isInFixAll !== false)) continue;
                var candidateKey = findings[i].id + ':' + JSON.stringify(candidate.edits);
                if (rejected[candidateKey]) continue;
                var at = foundIndex(findings[i]);
                if (isFoundOnly && at === -1) continue;
                var fixedSql = applyEdits(current, candidate.edits);
                if (currentErrors === null) currentErrors = parseStrict(current).errors.length;
                var fixedErrors = parseStrict(fixedSql).errors.length;
                if (fixedErrors > currentErrors) {
                    rejected[candidateKey] = true;
                    continue;
                };
                target = {
                    id: findings[i].id,
                    sql: fixedSql,
                    errors: fixedErrors,
                    edits: candidate.edits,
                    at: at
                };
                break;
            };
            if (!target) break;
            if (target.at !== -1) found.splice(target.at, 1);
            found.forEach(function (f) { f.start = shiftedOffset(f.start, target.edits); });
            current = target.sql;
            currentErrors = target.errors;
            appliedCount++;
            appliedIds.push(target.id);
            findings = null;
        };
        if (!findings) findings = lint(current, context);
        return {
            sql: current,
            appliedCount: appliedCount,
            appliedIds: appliedIds,
            newCount: findings.filter(function (f) { return foundIndex(f) === -1; }).length
        };
    };

    // ==================================================================
    // Results paging: REST chunks past the free window
    // ==================================================================
    /* A results page whose last row is within these rows is read without an API call. It must equal
     * FREE_READ_MAX_ROWS in the Backend, which a build test checks. */
    var FREE_READ_MAX_ROWS = 2000;
    /* The rows one REST chunk may hold. Each divides FREE_READ_MAX_ROWS, so the free window always ends on a chunk boundary. */
    var RESULT_CHUNK_SIZES = [2000, 1000, 500, 400, 250, 200];
    /* How many chunks one grid keeps: the least recently used one goes first. */
    var RESULT_CHUNK_CACHE_MAX = 5;

    /**
     * @function exportPageSize
     * @description The rows per REST page for Export CSV, from the number of columns (M7). Each page is one rowset call plus one server-side Stringify of the page, so a wide result gets smaller pages: 250,000 cells per page, in whole hundreds, from 200 to 2,500 rows.
     * @param {number} columnCount - How many columns the results have.
     * @returns {number} The page size.
     */
    function exportPageSize(columnCount) {
        var size = Math.floor(250000 / Math.max(1, columnCount) / 100) * 100;
        return Math.min(2500, Math.max(200, size));
    };

