            var sqlLines = isSide ? item.conditions : item.conditions.map(function (condition, i) { return (i === 0 ? 'ON ' : 'AND ') + condition; });
            if (item.mode === 'join') sqlLines.unshift(item.table + ' AS ' + item.alias);
